import { z } from "zod";

// ==========================================
// 1. Enums
// ==========================================

export const AccountKindEnum = z.enum(["deploy_key", "service_account", "bot"]);
export type AccountKind = z.infer<typeof AccountKindEnum>;

export const PersonStatusEnum = z.enum(["active", "departed"]);
export type PersonStatus = z.infer<typeof PersonStatusEnum>;

export const EvidenceRecordTypeEnum = z.enum(["commit", "ticket", "deploy_log", "policy"]);
export type EvidenceRecordType = z.infer<typeof EvidenceRecordTypeEnum>;

export const ClaimKindEnum = z.enum(["owner", "purpose"]);
export type ClaimKind = z.infer<typeof ClaimKindEnum>;

export const ReasonCodeEnum = z.enum(["R1", "R2", "R3", "R4", "R5"]);
export type ReasonCode = z.infer<typeof ReasonCodeEnum>;

export const OwnerStatusEnum = z.enum(["verified", "supported", "conflicting", "no_evidence"]);
export type OwnerStatus = z.infer<typeof OwnerStatusEnum>;

export const PurposeStatusEnum = z.enum(["verified", "supported", "no_evidence"]);
export type PurposeStatus = z.infer<typeof PurposeStatusEnum>;

export const GhostTypeEnum = z.enum(["LOST", "FORGOTTEN", "LONELY", "INNOCENT", "NOT_GHOST"]);
export type GhostType = z.infer<typeof GhostTypeEnum>;

export const HealthComponentStatusEnum = z.enum(["ok", "not_configured", "unavailable"]);
export type HealthComponentStatus = z.infer<typeof HealthComponentStatusEnum>;

// ==========================================
// 2. Domain Schemas
// ==========================================

export const AccountSchema = z.object({
  account_id: z.string().min(1),
  kind: AccountKindEnum,
  created_at: z.string().datetime(),
  last_used_at: z.string().datetime().nullable(),
  permissions: z.array(z.string()),
  tags: z.array(z.string()),
  expires_at: z.string().datetime().nullable(),
}).strict();
export type Account = z.infer<typeof AccountSchema>;

export const PersonDirectoryEntrySchema = z.object({
  person_id: z.string().min(1),
  display_name: z.string().min(1),
  handles: z.array(z.string()),
  status: PersonStatusEnum,
  departed_at: z.string().datetime().nullable(),
}).strict();
export type PersonDirectoryEntry = z.infer<typeof PersonDirectoryEntrySchema>;

export const EvidenceRecordSchema = z.object({
  record_id: z.string().min(1),
  type: EvidenceRecordTypeEnum,
  ts: z.string().datetime(),
  author_handle: z.string().nullable(),
  assignee_handle: z.string().nullable(),
  actor_account_id: z.string().nullable(),
  content: z.string(),
  structured: z.boolean(),
}).strict();
export type EvidenceRecord = z.infer<typeof EvidenceRecordSchema>;

export const InvestigationClaimSchema = z.object({
  kind: ClaimKindEnum,
  account_id: z.string().min(1),
  person_id: z.string().nullable(),
  record_id: z.string().min(1),
  quote: z.string(),
  text: z.string(),
}).strict();
export type InvestigationClaim = z.infer<typeof InvestigationClaimSchema>;

export const RemovedClaimSchema = InvestigationClaimSchema.extend({
  reason_code: ReasonCodeEnum,
}).strict();
export type RemovedClaim = z.infer<typeof RemovedClaimSchema>;

export const CaseSchema = z.object({
  case_id: z.string().min(1),
  bundle_id: z.string().min(1),
  account_id: z.string().min(1),
  claims_accepted: z.array(InvestigationClaimSchema),
  claims_removed: z.array(RemovedClaimSchema),
  owner_status: OwnerStatusEnum,
  purpose_status: PurposeStatusEnum,
  ghost_type: GhostTypeEnum,
  model: z.string(),
  latency_ms: z.number().nonnegative(),
}).strict();
export type Case = z.infer<typeof CaseSchema>;

export const HealthStatusSchema = z.object({
  status: z.enum(["ok", "degraded", "unavailable"]),
  uptime: z.number().nonnegative(),
  timestamp: z.string().datetime(),
  mode: z.enum(["demo", "configured"]),
  checks: z.object({
    db: HealthComponentStatusEnum,
    model: HealthComponentStatusEnum,
    scores: HealthComponentStatusEnum,
  }).strict(),
}).strict();
export type HealthStatus = z.infer<typeof HealthStatusSchema>;

import { z } from "zod";

const ServerConfigSchema = z.object({
  NODE_ENV: z.enum(["development", "production", "test"]).default("development"),
  PORT: z.coerce.number().int().positive().default(3001),
  MONGODB_URI: z.string().optional(),
  OLLAMA_BASE_URL: z.string().url().default("http://127.0.0.1:11434"),
  OLLAMA_MODEL: z.string().default("gemma3:4b"),
  AUTH0_DOMAIN: z.string().optional(),
  AUTH0_CLIENT_ID: z.string().optional(),
  AUTH0_CLIENT_SECRET: z.string().optional(),
  AUTH0_AUDIENCE: z.string().optional(),
  GITHUB_SANDBOX_OWNER: z.string().optional(),
  GITHUB_SANDBOX_REPO: z.string().optional(),
  // TABPFN_TOKEN is explicitly forbidden in server runtime
});

export type ServerConfig = z.infer<typeof ServerConfigSchema>;

export function loadConfig(env: Record<string, string | undefined> = process.env): ServerConfig {
  // If TABPFN_TOKEN is passed, warn that it is ignored by server runtime
  if (env["TABPFN_TOKEN"]) {
    // Intentionally ignored; not added to config
  }

  const result = ServerConfigSchema.safeParse(env);
  if (!result.success) {
    const missingKeys = result.error.errors.map((e) => e.path.join(".")).join(", ");
    throw new Error(`Server configuration error: invalid or missing variables: ${missingKeys}`);
  }

  // Feature validation: if any Auth0 var is set, all required auth vars must be set
  const cfg = result.data;
  const hasSomeAuth0 = cfg.AUTH0_DOMAIN || cfg.AUTH0_CLIENT_ID || cfg.AUTH0_CLIENT_SECRET;
  if (hasSomeAuth0) {
    const missingAuth: string[] = [];
    if (!cfg.AUTH0_DOMAIN) missingAuth.push("AUTH0_DOMAIN");
    if (!cfg.AUTH0_CLIENT_ID) missingAuth.push("AUTH0_CLIENT_ID");
    if (!cfg.AUTH0_CLIENT_SECRET) missingAuth.push("AUTH0_CLIENT_SECRET");
    if (missingAuth.length > 0) {
      throw new Error(`Auth0 configuration error: missing required variables: ${missingAuth.join(", ")}`);
    }
  }

  return cfg;
}

import { HealthStatus, HealthComponentStatus } from "@keys/contracts";
import { ServerConfig } from "./config.js";

export interface DependencyCheckers {
  checkDb?: () => Promise<HealthComponentStatus>;
  checkModel?: () => Promise<HealthComponentStatus>;
  checkScores?: () => Promise<HealthComponentStatus>;
}

export async function computeHealthStatus(
  config: ServerConfig,
  startTime: number,
  checkers: DependencyCheckers = {},
): Promise<{ status: HealthStatus; httpStatus: number }> {
  // If external dependencies are not configured, they are "not_configured"
  let dbStatus: HealthComponentStatus = config.MONGODB_URI ? "ok" : "not_configured";
  if (config.MONGODB_URI && checkers.checkDb) {
    try {
      dbStatus = await checkers.checkDb();
    } catch {
      dbStatus = "unavailable";
    }
  }

  let modelStatus: HealthComponentStatus = "not_configured";
  if (config.OLLAMA_BASE_URL && checkers.checkModel) {
    try {
      modelStatus = await checkers.checkModel();
    } catch {
      modelStatus = "unavailable";
    }
  }

  let scoresStatus: HealthComponentStatus = "not_configured";
  if (checkers.checkScores) {
    try {
      scoresStatus = await checkers.checkScores();
    } catch {
      scoresStatus = "unavailable";
    }
  }

  // Any configured dependency that is unavailable causes overall degradation/503
  const hasUnavailableConfigured =
    dbStatus === "unavailable" || modelStatus === "unavailable" || scoresStatus === "unavailable";

  const isDemoMode = !config.MONGODB_URI;

  const overallStatus = hasUnavailableConfigured ? "unavailable" : "ok";
  const httpStatus = hasUnavailableConfigured ? 503 : 200;

  const healthPayload: HealthStatus = {
    status: overallStatus,
    uptime: Math.floor((Date.now() - startTime) / 1000),
    timestamp: new Date().toISOString(),
    mode: isDemoMode ? "demo" : "configured",
    checks: {
      db: dbStatus,
      model: modelStatus,
      scores: scoresStatus,
    },
  };

  return { status: healthPayload, httpStatus };
}

import express, { Express, Request, Response, NextFunction } from "express";
import cors from "cors";
import path from "path";
import { ServerConfig } from "./config.js";
import { computeHealthStatus, DependencyCheckers } from "./health.js";
import { MOCK_DEMO_CASE, MOCK_DEMO_RECORDS } from "./fixtures.js";

export function createApp(config: ServerConfig, checkers: DependencyCheckers = {}): Express {
  const app = express();
  const startTime = Date.now();

  app.use(cors({ origin: true }));
  app.use(express.json({ limit: "2mb" }));

  // Request logger in non-test
  if (config.NODE_ENV !== "test") {
    app.use((req: Request, _res: Response, next: NextFunction) => {
      console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
      next();
    });
  }

  // 1. Healthcheck endpoint (SPEC 5.7 & Stage 6 A-4)
  const handleHealth = async (_req: Request, res: Response) => {
    const { status, httpStatus } = await computeHealthStatus(config, startTime, checkers);
    res.status(httpStatus).json(status);
  };

  app.get("/healthz", handleHealth);
  app.get("/api/health", handleHealth);

  // 2. Walking skeleton: Case lookup endpoint (SPEC 5.7)
  app.get("/api/cases/:id", (req: Request, res: Response) => {
    const caseId = req.params.id;
    // Strict alphanumeric identifier check to prevent path traversal
    if (!/^[a-zA-Z0-9_-]+$/.test(caseId)) {
      return res.status(400).json({ error: "Invalid case ID format" });
    }

    if (caseId === MOCK_DEMO_CASE.case_id) {
      return res.status(200).json(MOCK_DEMO_CASE);
    }

    return res.status(404).json({ error: "Case not found" });
  });

  // 3. Walking skeleton: Evidence Record lookup endpoint (SPEC 5.7)
  app.get("/api/records/:id", (req: Request, res: Response) => {
    const recordId = req.params.id;
    if (!/^[a-zA-Z0-9_-]+$/.test(recordId)) {
      return res.status(400).json({ error: "Invalid record ID format" });
    }

    const record = MOCK_DEMO_RECORDS.find((r) => r.record_id === recordId);
    if (!record) {
      return res.status(404).json({ error: "Record not found" });
    }

    return res.status(200).json(record);
  });

  // Serve static client assets in production if built
  if (config.NODE_ENV === "production") {
    const clientDist = path.resolve(process.cwd(), "client/dist");
    app.use(express.static(clientDist));
    app.get("*", (req: Request, res: Response, next: NextFunction) => {
      if (req.path.startsWith("/api") || req.path === "/healthz") {
        return next();
      }
      res.sendFile(path.join(clientDist, "index.html"), (err) => {
        if (err) next();
      });
    });
  }

  // 404 handler for unmatched routes
  app.use((_req: Request, res: Response) => {
    res.status(404).json({ error: "Not found" });
  });

  // Global safe error handler (Stage 6 A-2: never leak stack traces or internal paths)
  app.use((err: Error, _req: Request, res: Response, _next: NextFunction) => {
    const isProduction = config.NODE_ENV === "production";
    const safeMessage = isProduction ? "Internal server error" : err.message;
    res.status(500).json({ error: safeMessage });
  });

  return app;
}

